<?php
namespace Modules\StockTransferNew\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\StockTransferNew\Entities\StockTransferTemplate; use Modules\StockTransferNew\Services\StockTransferTemplateService;
class TemplateController extends Controller { public function index(StockTransferTemplateService $service){ return view('stocktransfernew::templates.index',['templates'=>$service->listForBusiness()]); } public function create(){ return view('stocktransfernew::templates.form',['template'=>new StockTransferTemplate()]); } public function store(Request $request,StockTransferTemplateService $service){ $service->create($this->payload($request)); return redirect()->route('stock-transfer-new.templates.index')->with('status','Template saved.'); } public function edit(StockTransferTemplate $template){ return view('stocktransfernew::templates.form',compact('template')); } public function update(Request $request,StockTransferTemplate $template,StockTransferTemplateService $service){ $service->update($template,$this->payload($request)); return redirect()->route('stock-transfer-new.templates.index')->with('status','Template updated.'); } public function destroy(StockTransferTemplate $template){ $template->delete(); return redirect()->back()->with('status','Template deleted.'); } protected function payload(Request $request): array { $request->validate(['name'=>'required|string|max:191']); return $request->only(['name','from_location_id','from_store_id','to_location_id','to_store_id','is_active']) + ['lines_json'=>[]]; } }
